insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_9_v1'
from (values
('128.23.c.1.A',3,'An eighth grader summarizes a speaker''s argument aloud before asking a question. This shows the listener is:','["interpreting the message actively", "ignoring the message", "copying notes silently", "changing the topic"]'::jsonb,0,'Summarizing and questioning are active listening moves.','original'),
('128.23.c.1.A',3,'Which comment builds on a classmate''s point during discussion?','["Whatever.", "That connects to what Dani said about funding, and I would add that costs vary by region.", "Can I go next, about something else?", "I was not listening."]'::jsonb,1,'Building on ideas links the conversation.','original'),
('128.23.c.1.B',3,'Complex oral instructions for a science demonstration often require a student to:','["skip the order", "follow without listening", "restate each step, then ask a question about any unclear step", "memorize only the first step"]'::jsonb,2,'Restating and questioning ensure accuracy.','original'),
('128.23.c.1.B',3,'A speaker gives six oral steps. The best way to retain them is to:','["trust memory alone", "wait to be told again", "ignore the last steps", "jot short notes and repeat them back"]'::jsonb,3,'Notes and repeating improve recall.','original'),
('128.23.c.1.C',3,'An organized presentation with a specific point of view should have:','["a clear opening, supporting points and a closing", "no thesis", "jokes only", "random order"]'::jsonb,0,'Structure supports the point of view.','original'),
('128.23.c.1.C',3,'A presenter strengthens a stance by:','["reading from a slide only", "using evidence and signaling transitions between points", "speaking off-topic", "hiding the position"]'::jsonb,1,'Evidence and transitions build persuasion.','original'),
('128.23.c.1.D',3,'A speaker compares a school''s budget to a household budget to explain a point. This device is an:','["index", "rhyme", "analogy", "citation"]'::jsonb,2,'An analogy compares two things to clarify.','original'),
('128.23.c.1.D',3,'Which adds an anecdote to an argument for later school start times?','["Start times are numbers.", "Mornings happen.", "Schools exist.", "Last fall, my cousin fell asleep in first period three days in a row."]'::jsonb,3,'An anecdote is a short personal story used as support.','original'),
('128.23.c.1.E',3,'A student plans a meeting agenda with goals and deadlines to:','["keep the group focused and on schedule", "avoid collaboration", "hide the goals", "lengthen the meeting"]'::jsonb,0,'Agendas organize collaboration.','original'),
('128.23.c.1.E',3,'When a group disagrees, a collaborative member should:','["end the meeting", "listen, restate the concern and propose a compromise", "stop speaking", "insist on the first idea"]'::jsonb,1,'Compromise builds group progress.','original'),
('128.23.c.1.F',3,'Contextualized oral language means using words and tone suited to:','["only written work", "no one in particular", "the listener, setting and purpose", "only math"]'::jsonb,2,'Language shifts with context.','original'),
('128.23.c.1.F',3,'Which phrase fits a respectful conversation with an adult mentor?','["Hurry up.", "Yeah, whatever.", "I don''t care.", "Thank you for your time; may I ask a follow-up question?"]'::jsonb,3,'Respectful language suits the setting.','original'),
('128.23.c.10.A',3,'An op-ed about water conservation ends with a call to action. The author''s purpose is to:','["persuade readers to change behavior", "tell a legend", "describe a dream", "rhyme"]'::jsonb,0,'Calls to action persuade.','original'),
('128.23.c.10.A',3,'Which question best identifies an author''s message?','["How many pages are there?", "What larger idea does the text want readers to remember?", "What size is the font?", "Who printed the book?"]'::jsonb,1,'Message is the central takeaway.','original'),
('128.23.c.10.B',3,'A history chapter that shows how one event caused the next uses which structure?','["compare and contrast", "description only", "cause and effect", "definition"]'::jsonb,2,'It links causes to results.','original'),
('128.23.c.10.B',3,'A text that lists pros and cons of a policy supports an author''s purpose to:','["describe a place", "narrate a plot", "entertain with jokes", "help readers weigh both sides"]'::jsonb,3,'Structure matches purpose.','original'),
('128.23.c.10.C',3,'A pull quote and a sidebar in a magazine feature are used to:','["highlight key ideas and add related details", "replace the headline", "hide the story", "shorten the title"]'::jsonb,0,'Print features emphasize and extend.','original'),
('128.23.c.10.C',3,'A line graph in a news article helps readers to:','["count syllables", "see a trend over time", "find rhyming words", "read the credits"]'::jsonb,1,'Graphs show trends.','original'),
('128.23.c.10.D',3,'An extended metaphor compares:','["two titles", "two words in one phrase", "two things across several lines or paragraphs", "two rhymes"]'::jsonb,2,'It develops one comparison at length.','original'),
('128.23.c.10.D',3,'A poem describes life as a long road, with turns, detours and a distant horizon. This is:','["a citation", "a pun", "a rhyme scheme", "an extended metaphor"]'::jsonb,3,'The road comparison runs throughout.','original'),
('128.23.c.10.E',4,'A story told in alternating chapters by two different narrators uses:','["multiple points of view", "omniscient only", "no point of view", "second person only"]'::jsonb,0,'Different narrators give different perspectives.','original'),
('128.23.c.10.E',4,'Irony occurs when:','["everything matches expectations", "the outcome is the opposite of what is expected", "the author uses rhyme", "the characters never speak"]'::jsonb,1,'Irony involves surprising contrast.','original'),
('128.23.c.10.F',3,'Short, clipped sentences and ominous words create a mood that is:','["dreamy", "peaceful", "tense and foreboding", "humorous"]'::jsonb,2,'Diction and syntax shape mood.','original'),
('128.23.c.10.F',3,'A narrator''s voice that is wry and sarcastic produces a tone best described as:','["bashful", "neutral", "reverent", "mocking"]'::jsonb,3,'Sarcasm makes tone mocking.','original'),
('128.23.c.10.G',4,'An analogy in an editorial helps the author to:','["explain an unfamiliar idea by comparing it to a familiar one", "change the topic", "list sources", "rhyme"]'::jsonb,0,'Analogies clarify.','original'),
('128.23.c.10.G',4,'Juxtaposition places two contrasting things side by side to:','["make them identical", "highlight their differences", "remove the contrast", "hide their meaning"]'::jsonb,1,'Contrast reveals meaning.','original'),
('128.23.c.11.A',3,'A student wants to advocate for a new bike lane. The most appropriate genre is:','["a recipe", "a haiku", "an argumentative essay or letter", "a script"]'::jsonb,2,'Advocacy fits argument.','original'),
('128.23.c.11.A',3,'Planning a first draft might involve:','["printing the final copy", "grading it", "hiding the topic", "outlining, brainstorming and considering the audience"]'::jsonb,3,'Planning precedes drafting.','original'),
('128.23.c.11.B.i',3,'A hook in an introduction is meant to:','["capture the reader''s attention", "end the essay", "repeat the title", "list sources"]'::jsonb,0,'Hooks engage readers.','original'),
('128.23.c.11.B.i',3,'A conclusion that offers a final thought rather than merely repeating the thesis shows:','["poor transitions", "purposeful structure", "lack of planning", "missing evidence"]'::jsonb,1,'Strong endings add closure.','original'),
('128.23.c.11.B.ii',3,'Which sentence adds depth of thought to an essay about social media?','["Apps are popular.", "People use phones.", "Constant comparison online can reshape how teens judge their own success.", "Social media exists."]'::jsonb,2,'Insightful analysis shows depth.','original'),
('128.23.c.11.B.ii',3,'Specific facts and details are best used to:','["fill space", "replace the thesis", "avoid analysis", "support the controlling idea"]'::jsonb,3,'Details back up the central idea.','original'),
('128.23.c.11.C',3,'Revising for sentence variety includes:','["mixing short and long sentences and different openers", "using only fragments", "deleting punctuation", "starting every sentence the same way"]'::jsonb,0,'Variety improves flow.','original'),
('128.23.c.11.C',3,'Revising for word choice means:','["adding filler", "replacing vague words with precise, vivid ones", "changing the topic", "repeating words"]'::jsonb,1,'Precision improves clarity.','original'),
('128.23.c.11.D.i',3,'A run-on sentence can be fixed by:','["removing all punctuation", "deleting the verb", "adding a conjunction with a comma or using a semicolon", "adding more clauses"]'::jsonb,2,'Punctuation separates independent clauses.','original'),
('128.23.c.11.D.i',3,'A complex sentence contains:','["only fragments", "a single phrase", "two independent clauses only", "an independent clause and at least one dependent clause"]'::jsonb,3,'This is the definition.','original'),
('128.23.c.11.D.ii',3,'Which sentence uses the passive voice?','["The trophy was awarded to the team.", "They celebrated the win.", "The coach awarded the trophy to the team.", "The team won the trophy."]'::jsonb,0,'The subject receives the action.','original'),
('128.23.c.11.D.ii',3,'Why might a writer choose the active voice?','["it lengthens sentences", "it is usually more direct and clear", "it hides the actor", "it removes verbs"]'::jsonb,1,'Active voice is clearer.','original'),
('128.23.c.11.D.iii',3,'Which conjunctive adverb signals a result?','["likewise", "meanwhile", "consequently", "however"]'::jsonb,2,'Consequently shows effect.','original'),
('128.23.c.11.D.iv',4,'Which verb is correct? ''The list of rules ___ posted by the door.''','["are", "were", "be", "is"]'::jsonb,3,'The subject is list.','original'),
('128.23.c.11.D.iv',4,'In ''The students in the front row take notes,'' the verb take agrees with:','["the plural noun before the preposition", "the adjective front", "the noun after the preposition", "the object notes"]'::jsonb,0,'The prepositional phrase does not change agreement.','original'),
('128.23.c.11.D.v',3,'Which sentence has a pronoun-antecedent error?','["Each student brought his or her book.", "Everyone should bring their own pencil, and he will be ready.", "The teacher handed back her papers.", "The dogs wagged their tails."]'::jsonb,1,'The pronoun shifts without a clear antecedent.','original'),
('128.23.c.11.D.v',3,'Which pronoun agrees with ''neither of the girls''?','["their", "them", "her", "its"]'::jsonb,2,'Neither is singular.','original'),
('128.23.c.11.D.vi',3,'A dependent clause cannot stand alone because it:','["has no punctuation", "is always long", "has no words", "does not express a complete thought"]'::jsonb,3,'It depends on an independent clause.','original'),
('128.23.c.11.D.vii',3,'Which title should be capitalized before a person''s name in a sentence?','["Professor", "teacher job", "school job", "adult"]'::jsonb,0,'A title directly before a name is capitalized.','original'),
('128.23.c.11.D.vii',3,'Which common noun should NOT be capitalized in running text?','["Canada", "mountain", "Monday", "Mount Everest"]'::jsonb,1,'Common nouns are lowercase.','original'),
('128.23.c.11.D.viii',3,'Commas set off a nonrestrictive phrase in:','["My cousin a talented, drummer joined the band.", "My, cousin a talented drummer joined the band.", "My cousin, a talented drummer, joined the band.", "My cousin a talented drummer joined, the band."]'::jsonb,2,'The phrase adds extra information.','original'),
('128.23.c.11.D.ix',3,'Which word completes the sentence? ''The principal''s speech had a strong ___ on students.''','["affect", "afect", "effekt", "effect"]'::jsonb,3,'Effect is the noun meaning result.','original'),
('128.23.c.11.D.ix',3,'Which sentence uses the correct form? ''The team lost ___ final game.''','["its", "its''", "it''s", "it"]'::jsonb,0,'Its is the possessive form.','original'),
('128.23.c.11.E',2,'Publishing for an appropriate audience means:','["keeping a draft private forever", "presenting the work in a format suited to readers", "changing the topic", "hiding the work"]'::jsonb,1,'Format fits audience.','original'),
('128.23.c.11.E',2,'A student might publish a research report as:','["an unlabeled page", "a sealed note", "a slide presentation for classmates", "a blank file"]'::jsonb,2,'Publishing shares work.','original'),
('128.23.c.12.A',3,'A personal narrative becomes stronger when the writer adds:','["a table of contents", "a bibliography", "random facts", "reflection on the lesson learned"]'::jsonb,3,'Reflection adds meaning.','original'),
('128.23.c.12.A',3,'Which poetic device repeats the same initial consonant sound?','["alliteration", "simile", "irony", "analogy"]'::jsonb,0,'Alliteration repeats beginning sounds.','original'),
('128.23.c.12.B',3,'A multi-paragraph informational essay should develop the thesis with:','["only questions", "organized body paragraphs containing facts", "only rhymes", "only opinions"]'::jsonb,1,'Body paragraphs develop the thesis.','original'),
('128.23.c.12.B',3,'Which transition fits the start of a final body paragraph?','["Meanwhile in unrelated news,", "Once upon a time,", "Finally,", "Anyway,"]'::jsonb,2,'Finally signals the last point.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_9_v1'
from (values
('128.23.c.12.C',3,'A multi-paragraph argument should include:','["only rhymes", "only anecdotes", "only statistics", "a claim, reasons, evidence and a response to the counterargument"]'::jsonb,3,'These are core components.','original'),
('128.23.c.12.C',3,'A strong argumentative thesis:','["takes a clear, debatable position", "asks a question only", "states a fact", "lists topics"]'::jsonb,0,'A thesis states a position.','original'),
('128.23.c.12.D',3,'A letter requesting information from a company should:','["demand an answer rudely", "state exactly what is needed and thank the reader", "omit the question", "use slang throughout"]'::jsonb,1,'Clarity and courtesy get results.','original'),
('128.23.c.12.D',3,'A complaint letter should propose:','["a threat", "nothing", "a reasonable solution", "an insult"]'::jsonb,2,'Constructive complaints suggest remedies.','original'),
('128.23.c.13.A',3,'Which research question is most focused?','["Is dust bad?", "What is history?", "Who farms?", "How did the Dust Bowl change farming practices in Texas?"]'::jsonb,3,'It has a specific topic and scope.','original'),
('128.23.c.13.A',3,'A teacher-guided question differs from a student-selected question because:','["the teacher helps set the question", "it is a quotation", "it is longer", "it has no answer"]'::jsonb,0,'The teacher provides direction.','original'),
('128.23.c.13.B',3,'A research plan should be revised when:','["a source is cited", "new findings change the direction of the inquiry", "the paper is finished", "the topic is irrelevant"]'::jsonb,1,'Flexibility improves research.','original'),
('128.23.c.13.C',3,'A secondary set of questions helps refine the main question by:','["replacing the topic", "adding unrelated ideas", "revealing gaps and narrowing the focus", "ending the project"]'::jsonb,2,'Secondary questions clarify scope.','original'),
('128.23.c.13.C',3,'If initial answers show a research question is too narrow, the researcher should:','["abandon research", "copy another", "avoid new questions", "broaden it to allow enough sources"]'::jsonb,3,'Adjust scope as needed.','original'),
('128.23.c.13.D',3,'Relevant information is best located by:','["using keywords, tables of contents and indexes", "guessing", "reading randomly", "skipping headings"]'::jsonb,0,'Navigation tools save time.','original'),
('128.23.c.13.D',3,'A researcher gathers information from a variety of sources to:','["shorten notes", "get multiple perspectives", "repeat one idea", "avoid evidence"]'::jsonb,1,'Varied sources increase reliability.','original'),
('128.23.c.13.E',3,'A recorded interview with a veteran is a:','["secondary source", "title", "primary source", "fallacy"]'::jsonb,2,'It is a firsthand account.','original'),
('128.23.c.13.E',3,'A textbook summary of a battle written decades later is a:','["primary source", "diary", "speech", "secondary source"]'::jsonb,3,'It interprets earlier events.','original'),
('128.23.c.13.F',3,'Synthesizing sources goes beyond summary by:','["combining ideas to form a new conclusion", "copying quotes", "removing evidence", "listing titles"]'::jsonb,0,'Synthesis builds understanding.','original'),
('128.23.c.13.F',3,'Which sentence synthesizes?','["The letters are old.", "Together, the census data and the letters show families moved west for cheaper land.", "Families lived somewhere.", "The census data is a table."]'::jsonb,1,'It joins both sources into a conclusion.','original'),
('128.23.c.13.G',3,'Paraphrasing correctly requires:','["omitting the source", "changing a few words", "restating ideas in your own words and citing the source", "copying phrases without credit"]'::jsonb,2,'Paraphrase needs new wording and credit.','original'),
('128.23.c.13.H.i',4,'Omission is a form of bias when a source:','["lists all viewpoints", "cites experts", "provides context", "leaves out facts that would weaken its argument"]'::jsonb,3,'What is left out can mislead.','original'),
('128.23.c.13.H.i',4,'Which source is most credible for the effects of vaccines?','["a peer-reviewed study from a medical journal", "an anonymous comment", "a personal rumor", "a viral meme"]'::jsonb,0,'Peer review adds reliability.','original'),
('128.23.c.13.H.ii',4,'''Everyone is buying this phone, so you should too'' is a:','["citation", "bandwagon appeal", "summary", "statistic"]'::jsonb,1,'It urges you to join the crowd.','original'),
('128.23.c.13.H.ii',4,'Loaded language is:','["statistics", "neutral facts", "words chosen to stir strong emotion or bias", "quotations"]'::jsonb,2,'Loaded words sway feelings.','original'),
('128.23.c.13.I',3,'A parenthetical citation in an essay tells the reader:','["the font used", "the page color", "the essay length", "where a quotation or idea came from"]'::jsonb,3,'Citations credit sources.','original'),
('128.23.c.13.I',3,'Using source materials ethically includes:','["citing all borrowed ideas and avoiding fabrication", "copying silently", "inventing evidence", "hiding sources"]'::jsonb,0,'Ethics requires honesty.','original'),
('128.23.c.13.J',3,'A student presents research as a website with video and text. This is:','["an oral-only delivery", "a multimodal delivery", "an unrelated delivery", "a written-only delivery"]'::jsonb,1,'It blends modes.','original'),
('128.23.c.13.J',3,'A good mode of delivery matches:','["the font", "the file size", "the audience and purpose", "the paper color"]'::jsonb,2,'Mode should suit audience.','original'),
('128.23.c.2.A',3,'Phonetic knowledge helps a reader decode:','["only titles", "only pictures", "only numbers", "unfamiliar multisyllabic words"]'::jsonb,3,'Phonics supports decoding.','original'),
('128.23.c.2.A',3,'The letters ''ph'' in ''phrase'' make which sound?','["/f/", "/p/", "/s/", "/h/"]'::jsonb,0,'Ph sounds like f.','original'),
('128.23.c.2.B',2,'Writing answers legibly ensures that:','["the paper looks decorated", "the reader can understand what was written", "the page is full", "the pen runs out"]'::jsonb,1,'Legibility aids communication.','original'),
('128.23.c.2.B',2,'A complete thought in writing contains:','["only an adjective", "only a verb", "a subject and predicate", "only a noun"]'::jsonb,2,'Complete thoughts have both.','original'),
('128.23.c.3.A',3,'Syllabication in a dictionary entry shows:','["its page number", "its length in pages", "its author", "how a word is divided into syllables"]'::jsonb,3,'Syllable breaks help with pronunciation.','original'),
('128.23.c.3.A',3,'A word''s etymology tells:','["where the word came from", "its font", "how many pages", "who published it"]'::jsonb,0,'Etymology is word history.','original'),
('128.23.c.3.B',3,'Context within or beyond a paragraph can clarify an ambiguous word by:','["removing it", "providing definitions, examples or contrasts", "changing its spelling", "making it longer"]'::jsonb,1,'Context supplies meaning.','original'),
('128.23.c.3.B',3,'In ''The senator''s candor surprised reporters, who were used to evasive answers,'' candor means:','["anger", "confusion", "honesty", "evasion"]'::jsonb,2,'Contrast with evasive shows candor means honest.','original'),
('128.23.c.3.C',3,'The Greek root ''chron'' in chronology means:','["sound", "light", "earth", "time"]'::jsonb,3,'Chron means time.','original'),
('128.23.c.3.C',3,'The Latin root ''dict'' in dictate and predict means:','["to say", "to carry", "to write", "to see"]'::jsonb,0,'Dict relates to speaking.','original'),
('128.23.c.3.E',3,'The words ''wind'' (moving air) and ''wind'' (to turn) are:','["homophones", "homographs", "antonyms", "synonyms"]'::jsonb,1,'Same spelling, different meaning and sound.','original'),
('128.23.c.3.E',3,'Which pair is commonly confused?','["tall and high", "fast and quick", "accept and except", "big and large"]'::jsonb,2,'They sound similar but differ in meaning.','original'),
('128.23.c.3.F',3,'The idiom ''bite the bullet'' means:','["eat a snack", "shoot a target", "cook lunch", "face something difficult with courage"]'::jsonb,3,'Idioms are figurative.','original'),
('128.23.c.3.F',3,'Antonyms are words with:','["opposite meanings", "the same spelling", "similar meanings", "the same sound"]'::jsonb,0,'Antonyms oppose each other.','original'),
('128.23.c.4',2,'Developing foundational language skills benefits a student because:','["skills never connect", "listening, speaking, reading and writing support each other", "only writing matters", "only reading matters"]'::jsonb,1,'Skills are interrelated.','original'),
('128.23.c.4',2,'Reading aloud and discussing a text builds:','["only handwriting", "only spelling tests", "fluency and comprehension", "no skills"]'::jsonb,2,'Oral work supports reading.','original'),
('128.23.c.5',2,'A student reads a book, discusses it and writes a review. This integrates:','["only math", "only drawing", "no skills", "reading, speaking and writing"]'::jsonb,3,'Several skills work together.','original'),
('128.23.c.5',2,'Taking notes while listening to a lecture combines:','["listening and writing", "only drawing", "only reading", "only speaking"]'::jsonb,0,'It joins two skills.','original'),
('128.23.c.6.A',3,'Setting a purpose before reading a science article might be:','["to count pages", "to find evidence that supports a hypothesis", "to find the longest word", "to skip the abstract"]'::jsonb,1,'Purpose focuses reading.','original'),
('128.23.c.6.A',3,'A self-selected text is usually chosen because it:','["is required", "is unreadable", "interests the reader", "is hardest"]'::jsonb,2,'Self-selected means chosen.','original'),
('128.23.c.6.B',3,'Generating questions after reading helps readers to:','["forget the text", "skip pages", "avoid thinking", "reflect and deepen understanding"]'::jsonb,3,'Questions extend thinking.','original'),
('128.23.c.6.B',3,'Which is a strong question to ask while reading a mystery?','["What clues suggest who the culprit might be?", "What is the page number?", "What color is the cover?", "What font is used?"]'::jsonb,0,'It prompts analysis.','original'),
('128.23.c.6.C',3,'Predictions can be made using:','["only the font", "text features, genre and prior knowledge", "only the title page", "only the page count"]'::jsonb,1,'Multiple clues support predictions.','original'),
('128.23.c.6.C',3,'A reader confirms a prediction when:','["the font changes", "the title changes", "later events match what was predicted", "the page turns"]'::jsonb,2,'Evidence confirms predictions.','original'),
('128.23.c.6.D',3,'Mental images are strongest when a reader notices:','["chapter lengths", "author names", "page numbers", "sensory details in the text"]'::jsonb,3,'Sensory detail supports visualizing.','original'),
('128.23.c.6.D',3,'Visualizing a historical event helps a reader to:','["understand how it might have looked and felt", "ignore details", "avoid thinking", "skip the dates"]'::jsonb,0,'Mental images deepen understanding.','original'),
('128.23.c.6.E',3,'Connecting a novel''s theme to current events is a connection to:','["the glossary", "society", "the index", "the font"]'::jsonb,1,'Text-to-world connection.','original'),
('128.23.c.6.E',3,'Noticing similarities between two books'' characters is a connection to:','["the weight", "the cover", "another text", "the price"]'::jsonb,2,'Text-to-text connection.','original'),
('128.23.c.6.F',3,'''Marta rehearsed her speech in the mirror for an hour.'' A reader can infer she:','["does not care", "has no speech", "forgot her speech", "cares about doing well"]'::jsonb,3,'Rehearsal signals concern.','original'),
('128.23.c.6.F',3,'Which supports an inference that a character is brave?','["She stepped forward when nobody else would.", "She had brown hair.", "She lived in a town.", "She owned a bike."]'::jsonb,0,'Actions show bravery.','original'),
('128.23.c.6.G',3,'To evaluate details for key ideas, a reader decides which details:','["are in bold", "are essential to the main idea", "appear first", "are longest"]'::jsonb,1,'Key ideas relate to the main idea.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
